export const meta = {
  name: 't2mv-apply-review-fixes',
  description: 'Apply verified review findings per chapter file, then independently re-check each fix for regressions',
  whenToUse: 'After workflows/4_continuity_review.js: pass its result.items as args.items. Args from bin/t2mv fixes <project> --items=<file.json>.',
  phases: [
    { title: 'Fix', detail: 'one agent per chapter file applies its findings' },
    { title: 'Check', detail: 'independent agent re-renders and confirms each fix' },
  ],
}
// ---- args (generated by `bin/t2mv fixes <project> --items=<file>`; see workflows/README.md) ----
// { buildDir, items: [{ tag, file, findings: [{t, severity, problem, fix}], extra? }], sharedChanges? }
const A = args || {}
if (!A.buildDir) throw new Error('missing args: buildDir')
if (!Array.isArray(A.items) || !A.items.length) throw new Error('missing args: items (the "items" array returned by workflows/4_continuity_review.js)')
const ROOT = A.buildDir
const SHARED = A.sharedChanges ? `Shared-engine changes ALREADY MADE by the director (do not edit shared files): ${A.sharedChanges}\n` : ''

const FIX = (it) => `You are fixing review findings in ONE chapter file of a hand-painted vertical music video. Root (run commands here): ${ROOT}. Your file: ${it.file} (edit ONLY this file). Read GUIDE.md quickly (hard rules: pure function of t, verbatim receipts only, checkquotes, faces/key action between y 260-1560, no logos).
${SHARED}Findings to fix (time, severity, problem, suggested fix; the suggestion is a guide and line numbers may have drifted):
${JSON.stringify(it.findings, null, 1)}
${it.extra || ''}
For each: fix it, then confirm visually with \`node render.mjs --stills=<times> --out=previews/fix/${it.tag}\` (Read the PNGs) and a contact sheet around it. Run \`node tools/checkquotes.mjs ${it.file}\` (only OK). Do NOT touch out/ (a full render may live there).
Final message: per finding, fixed/not and how; the exact time ranges (seconds) whose frames changed, as "ranges: a-b, c-d" on the last line.`

const CHS = { type: 'object', properties: { allFixed: { type: 'boolean' }, notes: { type: 'string' }, regressions: { type: 'array', items: { type: 'string' } } }, required: ['allFixed', 'notes', 'regressions'] }
const res = await pipeline(A.items,
  (it) => agent(FIX(it), { label: `fix:${it.tag}`, phase: 'Fix' }),
  (rep, it) => agent(`Independently verify fixes in a music video chapter. Root: ${ROOT} (read-only; don't touch out/). File ${it.file}. Findings that should now be fixed:\n${JSON.stringify(it.findings.map(f => ({ t: f.t, problem: f.problem })), null, 1)}\nFixer's report:\n${String(rep || '').slice(0, 2500)}\nRender stills at each finding time (+-0.1 s) into previews/check/${it.tag} and Read them. Also scan a contact sheet across the changed ranges for NEW breakage. Report per finding: fixed yes/no with what you see, plus any regressions.`, { label: `check:${it.tag}`, phase: 'Check', schema: CHS }).then(c => ({ tag: it.tag, file: it.file, report: String(rep || '').slice(0, 2500), check: c })),
)
const notFixed = res.filter(Boolean).filter(r => !(r.check && r.check.allFixed) || (r.check.regressions || []).length)
if (notFixed.length) log(`needs another pass: ${notFixed.map(r => r.tag).join(', ')}`)
return { results: res, needsAnotherPass: notFixed.map(r => r.tag), reminder: 'Frames are reused on resume: after any code change render with bin/t2mv render <project> --fresh (or delete only the changed ranges).' }
